import React,{useState} from "react";
import api from "../services/api";

export default function Dividend(){
  const [form,setForm]=useState({memberId:"3",ratePercent:"10"});
  const [data,setData]=useState(null),[err,setErr]=useState("");
  const submit=async e=>{e.preventDefault();try{setErr("");setData((await api.post("/dividends/calculate",{memberId:Number(form.memberId),ratePercent:Number(form.ratePercent)})).data)}catch(e){setData(null);setErr(e.response?.data?.message||"Calculation failed.")}};
  return <>
    <div className="page-head"><div><span className="eyebrow">MEMBER RETURNS</span><h2>Dividend Calculator</h2><p>Calculate a proposed dividend from share capital.</p></div></div>
    <form className="inline-form" onSubmit={submit}><input value={form.memberId} onChange={e=>setForm({...form,memberId:e.target.value})} placeholder="Member ID"/><input type="number" step="0.01" value={form.ratePercent} onChange={e=>setForm({...form,ratePercent:e.target.value})} placeholder="Rate %"/><button className="primary">Calculate</button></form>
    {err&&<div className="alert">{err}</div>}
    {data&&<div className="dividend-result"><span>CALCULATED DIVIDEND</span><strong>₹{data.calculatedDividend}</strong><div><b>{data.memberId}</b><small>Share capital ₹{data.shareCapital} • Rate {data.ratePercent}%</small></div><span className="badge warning">Approval required</span></div>}
  </>;
}
